import { useEffect, useState } from "react";
import { Link } from "react-router";
import MapCard, { MapCardSkeleton } from "../components/MapCard";
import type { MapSummary } from "../lib/maps";

type State =
  | { phase: "loading" }
  | { phase: "ready"; maps: MapSummary[] }
  | { phase: "error"; message: string };

interface PublicScan {
  shareId: string;
  sharePath: string;
  name?: string;
  updatedAt?: string;
}

/** Reads GET /api/scans/public. Older servers send no names, so those cards use the short ID. */
async function fetchPublicMaps(signal: AbortSignal): Promise<MapSummary[]> {
  const response = await fetch("/api/scans/public", { signal });
  if (!response.ok) throw new Error(`The server answered ${response.status}.`);
  const body = (await response.json()) as { scans?: PublicScan[] };
  return (body.scans ?? []).map((scan) => ({
    id: scan.shareId,
    name: scan.name ?? `Untitled map ${scan.shareId.slice(0, 6)}`,
    visibility: "public",
    sharePath: scan.sharePath,
    updated: scan.updatedAt,
  }));
}

export default function Community() {
  const [state, setState] = useState<State>({ phase: "loading" });
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    document.title = "Community · Not 404";
  }, []);

  useEffect(() => {
    const controller = new AbortController();
    setState({ phase: "loading" });
    fetchPublicMaps(controller.signal)
      .then((maps) => setState({ phase: "ready", maps }))
      .catch((error: unknown) => {
        if (controller.signal.aborted) return;
        setState({
          phase: "error",
          message: error instanceof TypeError ? "Couldn't reach the server." : (error as Error).message,
        });
      });
    return () => controller.abort();
  }, [attempt]);

  return (
    <div className="mx-auto max-w-6xl">
      <h1 className="font-display text-4xl leading-none font-black">Community</h1>
      <p className="mt-3 text-lg text-muted">Public maps anyone can open, no account needed.</p>

      {state.phase === "loading" ? (
        <div role="status" className="mt-6">
          <span className="sr-only">Loading public maps…</span>
          <ul className="grid grid-cols-2 gap-3 xl-text:max-sm:grid-cols-1 sm:grid-cols-3 md:gap-5 xl:grid-cols-4">
            {[0, 1, 2, 3].map((i) => (
              <li key={i}>
                <MapCardSkeleton />
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      {state.phase === "error" ? (
        <div role="alert" className="mt-8 rounded-2xl bg-surface p-5 ring-1 ring-rust/30">
          <p className="font-bold">Couldn't load community maps</p>
          <p className="mt-1 text-muted">{state.message}</p>
          <button
            type="button"
            onClick={() => setAttempt((n) => n + 1)}
            className="mt-4 min-h-11 rounded-full bg-coral px-5 font-bold text-ink"

