import { CalendarDays, Plus } from "lucide-react";
import { useEffect } from "react";
import { Link } from "react-router";
import { useMyEvents } from "../lib/events";

const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? "" : "s"}`;

/** /events: events you organize or joined. On phones this is the Events tab. */
export default function Events() {
  const { status, events, reload } = useMyEvents();
  useEffect(() => { document.title = "Events · Not 404"; }, []);

  return (
    <div className="mx-auto max-w-3xl">
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="font-display text-4xl leading-none font-black">Events</h1>
          <p className="mt-3 text-lg text-muted">Share a set of maps with everyone you invite.</p>
        </div>
        <Link to="/events/new" className="flex min-h-12 items-center gap-2 rounded-full bg-coral px-5 font-bold text-ink">
          <Plus className="size-5" aria-hidden />
          Create event
        </Link>
      </div>

      {status === "loading" && !events.length ? <p role="status" className="mt-8">Loading your events…</p> : null}
      {status === "error" ? (
        <div role="alert" className="mt-8 rounded-2xl bg-surface p-5 ring-1 ring-rust/30">
          <p className="font-bold">Couldn't load your events</p>
          <button type="button" onClick={reload} className="mt-3 min-h-11 rounded-full bg-coral px-5 font-bold text-ink">Try again</button>
        </div>
      ) : null}
      {status === "ready" && events.length === 0 ? (
        <div className="mt-8 rounded-2xl bg-surface p-6 ring-1 ring-forest/10">
          <p className="font-bold">No events yet</p>
          <p className="mt-1 text-muted">Create one and add your maps, or open an invite link someone sent you.</p>
        </div>
      ) : null}

      {events.length ? (
        <ul className="mt-8 grid gap-3">
          {events.map((event) => (
            <li key={event.id}>
              <Link to={`/events/${event.id}`} className="flex items-center gap-4 rounded-2xl bg-surface p-5 shadow-sm ring-1 ring-forest/10 hover:ring-forest/30">
                <CalendarDays className="size-8 shrink-0 text-forest" aria-hidden />
                <span className="min-w-0 flex-1">
                  <span className="block truncate font-display text-xl font-extrabold">{event.name}</span>
                  <span className="block text-sm text-muted">
                    {event.role === "organizer" ? "You organize this" : "Joined"} · {plural(event.mapCount, "map")} · {plural(event.memberCount, "member")}
                  </span>
                </span>
              </Link>
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

import { useEffect, useState, type FormEvent } from "react";
import { Link, useNavigate } from "react-router";
import { createEvent, useMyEvents } from "../lib/events";

const MAX_NAME = 200;

/** /events/new: name the event; maps and the invite link come next on its page. */
export default function NewEvent() {
  const navigate = useNavigate();
  const { reload } = useMyEvents();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => { document.title = "Create event · Not 404"; }, []);

  async function submit(event: FormEvent) {
    event.preventDefault();
    const cleanName = name.trim();
    if (!cleanName) { setError("Give the event a name."); return; }
    setSaving(true);
    setError(null);
    try {
      const created = await createEvent({ name: cleanName, ...(description.trim() ? { description: description.trim() } : {}) });
      reload();
      navigate(`/events/${created.event.id}`, { state: { created: true } });
    } catch (cause) {
      setError(cause instanceof Error ? `Couldn't create the event. ${cause.message}` : "Couldn't create the event.");
      setSaving(false);
    }
  }

  return (
    <div className="mx-auto max-w-lg">
      <Link to="/events" className="text-sm font-bold text-rust underline underline-offset-4">← Events</Link>
      <h1 className="mt-4 font-display text-4xl leading-none font-black">Create event</h1>
      <p className="mt-3 text-lg text-muted">
        Next you'll add maps and get an invite link. Everyone who joins can open those maps and get directions.
      </p>
      <form onSubmit={submit} className="mt-8 grid gap-5">
        <div className="grid gap-2">
          <label htmlFor="event-name" className="font-bold">Name</label>
          <input id="event-name" value={name} onChange={(e) => setName(e.target.value)} maxLength={MAX_NAME} required
            disabled={saving} placeholder="Hack Western 13" aria-describedby={error ? "event-error" : undefined}
            className="min-h-12 rounded-lg bg-surface px-3 text-lg ring-1 ring-forest/25" />
        </div>
        <div className="grid gap-2">
          <label htmlFor="event-description" className="font-bold">Description <span className="font-normal text-muted">(optional)</span></label>
          <textarea id="event-description" value={description} onChange={(e) => setDescription(e.target.value)} maxLength={4000}
            disabled={saving} rows={3} placeholder="Where to go and what to find there"
            className="rounded-lg bg-surface px-3 py-2 ring-1 ring-forest/25" />
        </div>
        {error ? <p id="event-error" role="alert" className="text-rust">{error}</p> : null}
        <button type="submit" disabled={saving}
          className="min-h-14 rounded-full bg-coral px-6 text-lg font-bold text-ink disabled:bg-forest/15 disabled:text-forest/60">
          {saving ? "Creating…" : "Create event"}
        </button>
      </form>
    </div>
  );
}

import { CalendarDays } from "lucide-react";
import { useEffect, useState } from "react";
import { Link, useLocation, useNavigate, useParams, useSearchParams } from "react-router";
import { useAuth } from "../lib/auth";
import { fetchInvite, joinEvent, useMyEvents, type InvitePreview } from "../lib/events";
import { loginHref } from "../lib/http";
import { ApiError } from "../lib/space-api";

type State = { phase: "loading" } | { phase: "ready"; invite: InvitePreview } | { phase: "invalid" } | { phase: "error"; message: string };

/** /events/:eventId/join?code=…: what an invite link opens. Signed-out visitors sign in first. */
export default function JoinEvent() {
  const { eventId = "" } = useParams();
  const [search] = useSearchParams();
  const code = search.get("code") ?? "";
  const location = useLocation();
  const navigate = useNavigate();
  const { status: auth } = useAuth();
  const { reload } = useMyEvents();
  const [state, setState] = useState<State>({ phase: "loading" });
  const [joining, setJoining] = useState(false);
  const [joinError, setJoinError] = useState<string | null>(null);

  useEffect(() => {
    if (!code) { setState({ phase: "invalid" }); return; }
    const controller = new AbortController();
    setState({ phase: "loading" });
    fetchInvite(eventId, code, controller.signal)
      .then((invite) => { setState({ phase: "ready", invite }); document.title = `Join ${invite.event.name} · Not 404`; })
      .catch((error) => {
        if (controller.signal.aborted) return;
        if (error instanceof ApiError && (error.status === 404 || error.status === 400)) setState({ phase: "invalid" });
        else setState({ phase: "error", message: error instanceof Error ? error.message : "Couldn't open this invite." });
      });
    return () => controller.abort();
  }, [eventId, code, auth]);

  async function join() {
    setJoining(true);
    setJoinError(null);
    try {
      await joinEvent(eventId, code);
      reload();
      navigate(`/events/${eventId}`, { replace: true });
    } catch (error) {
      setJoinError(error instanceof Error ? `Couldn't join. ${error.message}` : "Couldn't join.");
      setJoining(false);
    }
  }

  return (
    <div className="mx-auto max-w-lg">
      {state.phase === "loading" ? <p role="status">Opening invite…</p> : null}
      {state.phase === "invalid" ? (
        <div role="alert" className="rounded-2xl bg-surface p-6 ring-1 ring-rust/30">
          <h1 className="font-display text-2xl font-black">This invite link doesn't work</h1>
          <p className="mt-2 text-muted">It may be incomplete, or the organizer deleted the event. Ask them to send the link again.</p>
        </div>
      ) : null}
      {state.phase === "error" ? <p role="alert" className="text-rust">{state.message}</p> : null}
      {state.phase === "ready" ? (
        <section aria-labelledby="invite-title" className="rounded-2xl bg-surface p-6 shadow-sm ring-1 ring-forest/10">
          <CalendarDays className="size-10 text-forest" aria-hidden />
          <p className="mt-4 text-muted">{state.invite.organizer} invited you to</p>
          <h1 id="invite-title" className="font-display text-4xl leading-none font-black">{state.invite.event.name}</h1>
          {state.invite.event.description ? <p className="mt-3">{state.invite.event.description}</p> : null}
          <p className="mt-3 text-muted">
            {state.invite.mapCount === 1 ? "1 map" : `${state.invite.mapCount} maps`} with directions, for everyone who joins.
          </p>
          <div className="mt-6">
            {state.invite.role ? (
              <Link to={`/events/${eventId}`} className="flex min-h-14 items-center justify-center rounded-full bg-coral px-6 text-lg font-bold text-ink">
                You're in. Open the event
              </Link>
            ) : auth === "authenticated" ? (
              <button type="button" onClick={join} disabled={joining}
                className="min-h-14 w-full rounded-full bg-coral px-6 text-lg font-bold text-ink disabled:bg-forest/15 disabled:text-forest/60">
                {joining ? "Joining…" : "Join event"}
              </button>
            ) : auth === "loading" ? (
              <p role="status">Checking sign-in…</p>
            ) : (
              <>
                <a href={loginHref(location.pathname + location.search)} className="flex min-h-14 items-center justify-center rounded-full bg-coral px-6 text-lg font-bold text-ink">
                  Sign in to join
                </a>
                <p className="mt-2 text-center text-sm text-muted">You'll come back here after signing in.</p>
              </>
            )}
            {joinError ? <p role="alert" className="mt-3 text-rust">{joinError}</p> : null}
          </div>
        </section>
      ) : null}
    </div>
  );
}

